package com.hify.domain;
import jakarta.persistence.*; import java.io.Serializable; import java.time.Instant; import java.util.Objects;
@Entity @Table(name="agent_mcp_tool_bindings") @IdClass(AgentMcpToolBinding.Key.class)
public class AgentMcpToolBinding {@Id private String agentId;@Id private String serverId;@Id private String toolName;private Instant createdAt;protected AgentMcpToolBinding(){}public AgentMcpToolBinding(String a,String s,String t,Instant n){agentId=a;serverId=s;toolName=t;createdAt=n;}public String getAgentId(){return agentId;}public String getServerId(){return serverId;}public String getToolName(){return toolName;}public static class Key implements Serializable{public String agentId,serverId,toolName;public Key(){}@Override public boolean equals(Object o){return o instanceof Key k&&Objects.equals(agentId,k.agentId)&&Objects.equals(serverId,k.serverId)&&Objects.equals(toolName,k.toolName);}@Override public int hashCode(){return Objects.hash(agentId,serverId,toolName);}}}
